<h2>Extract the SEO signals from a public page</h2><p class="lead">Enter a public URL to inspect its title, description, canonical, robots, headings and social metadata.</p>
<div class="field full"><label for="targetUrl">Public page URL</label><input id="targetUrl" type="url" inputmode="url" value="https://toolboxkart.tech/seo/meta-tag-generator" placeholder="https://example.com/page"></div>
<div class="tool-actions"><button class="btn btn-primary" id="extract" type="button">Extract metadata</button><button class="btn btn-secondary" id="copy" type="button">Copy report</button></div>
<div class="notice"><strong>Privacy and safety:</strong> The URL is fetched by ToolboxKart's server-side extractor. Use public pages only. Requests are limited by protocol, response size and timeout controls; credentials and private URLs are not supported.</div>
<div class="result-box" id="result" hidden aria-live="polite"><div class="result-grid"><div class="metric"><span>HTTP status</span><strong id="status">—</strong></div><div class="metric"><span>Content type</span><strong id="ctype">—</strong></div><div class="metric"><span>Response size</span><strong id="size">—</strong></div></div><h3>Core SEO metadata</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Signal</th><th>Value</th></tr></thead><tbody id="core"></tbody></table></div><h3>Headings</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Level</th><th>Text</th></tr></thead><tbody id="headings"></tbody></table></div><h3>Social metadata</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody id="social"></tbody></table></div><h3>Technical checks</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Check</th><th>Finding</th></tr></thead><tbody id="checks"></tbody></table></div></div>
<div class="result-box" id="error" hidden><strong>Could not extract this URL.</strong><p id="errorText"></p></div>
<script>(()=>{const $=i=>document.getElementById(i);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const val=s=>String(s??'').trim()||'Not found';const row=(a,b)=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`;function setHidden(id,h){$(id).hidden=h}function formatBytes(n){if(!Number.isFinite(n)||n<0)return'—';if(n<1024)return n+' B';if(n<1024*1024)return (n/1024).toFixed(1)+' KB';return (n/1024/1024).toFixed(2)+' MB'}function render(d){$('status').textContent=(d.status||'—')+' '+(d.statusText||'');$('ctype').textContent=val(d.contentType);$('size').textContent=formatBytes(d.bytes);$('core').innerHTML=[row('Title',d.title),row('Meta description',d.description),row('Canonical',d.canonical),row('Robots',d.robots),row('Lang',d.lang),row('H1 count',d.h1Count),row('Viewport',d.viewport)].join('');$('headings').innerHTML=d.headings?.length?d.headings.map(h=>row(h.level,h.text)).join(''):'<tr><td colspan="2">No H1–H6 headings found.</td></tr>';const social=d.social||[];$('social').innerHTML=social.length?social.map(x=>row(x.name,x.value)).join(''):'<tr><td colspan="2">No Open Graph or Twitter card tags found.</td></tr>';$('checks').innerHTML=[row('Canonical URL',d.canonical?'Found':'Missing'),row('Meta description',d.description?'Found':'Missing'),row('Robots meta',d.robots?'Found':'Not declared'),row('H1 structure',d.h1Count===1?'One H1 found':d.h1Count===0?'No H1 found':d.h1Count+' H1 elements found'),row('Open Graph',d.ogCount?d.ogCount+' properties found':'None found'),row('Twitter card',d.twitterCount?d.twitterCount+' properties found':'None found')].join('');setHidden('error',true);setHidden('result',false);window._tkReport=[`URL: ${d.finalUrl||$('targetUrl').value}`,`HTTP: ${d.status||'—'} ${d.statusText||''}`,`Content-Type: ${d.contentType||'—'}`,`Size: ${formatBytes(d.bytes)}`,`Title: ${d.title||'Not found'}`,`Description: ${d.description||'Not found'}`,`Canonical: ${d.canonical||'Not found'}`,`Robots: ${d.robots||'Not found'}`,`Language: ${d.lang||'Not found'}`,`H1 count: ${d.h1Count}`,`Viewport: ${d.viewport||'Not found'}`,`Headings: ${(d.headings||[]).map(h=>h.level+': '+h.text).join(' | ')||'None'}`,`Social: ${social.map(x=>x.name+'='+x.value).join(' | ')||'None'}`].join('\n')}async function go(){const u=$('targetUrl').value.trim();if(!/^https?:\/\//i.test(u)){setHidden('result',true);setHidden('error',false);$('errorText').textContent='Enter a full public URL beginning with http:// or https://.';return}setHidden('result',true);setHidden('error',false);$('errorText').textContent='Fetching and analyzing the page…';try{const r=await fetch('/api/meta-extractor.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:u})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'The extractor returned an unexpected response.');render(d)}catch(e){$('errorText').textContent=e.message||'The request failed. Check the URL and try again.'}}$('extract').onclick=go;$('copy').onclick=()=>{if(window._tkReport)tkCopy(window._tkReport)};})();</script>
